import table from '../data/text/gemini.json';

/**
 * On-screen text pass. Every string shown to the player goes through tx(): if the rewritten script
 * (src/data/text/gemini.json, generated by scripts/gemini-write.mjs) has a line for it, that line is shown;
 * otherwise the original stays. Keys are the original strings; "{0}" marks a runtime value.
 */
const exact = new Map<string, string>(Object.entries(table as Record<string, string>));
const patterns: { re: RegExp; out: string }[] = [];
for (const [k, v] of exact) {
  if (!/\{\d\}/.test(k)) continue;
  const re = new RegExp('^' + k.replace(/[.*+?^$()|[\]\\]/g, '\\$&').replace(/\\?\{(\d)\\?\}/g, '(?<v$1>.*?)') + '$', 's');
  patterns.push({ re, out: v });
}

export function tx(s: string): string {
  if (!s) return s;
  const hit = exact.get(s);
  if (hit !== undefined) return hit;
  for (const p of patterns) {
    const m = p.re.exec(s);
    if (m) return p.out.replace(/\{(\d)\}/g, (_, i) => tx(m.groups?.['v' + i] ?? ''));
  }
  if (s.includes('\n')) return s.split('\n').map(tx).join('\n');
  return s;
}

/** Rewrites static menu text in the page once at boot. */
export function txDom(root: HTMLElement = document.body) {
  const w = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
  for (let n = w.nextNode(); n; n = w.nextNode()) {
    const t = n.nodeValue ?? '';
    const k = t.trim();
    if (k) { const v = tx(k); if (v !== k) n.nodeValue = t.replace(k, v); }
  }
  root.querySelectorAll<HTMLElement>('[aria-label]').forEach((el) => el.setAttribute('aria-label', tx(el.getAttribute('aria-label')!)));
}
